package dashboard.enterprise.agent.llm.usage;import dashboard.enterprise.agent.llm.model.LlmUsage;public final class CostEstimator{public LlmUsage estimate(int promptTokens,int completionTokens,double promptPerMillion,double completionPerMillion){double cost=(promptTokens/1_000_000d)*promptPerMillion+(completionTokens/1_000_000d)*completionPerMillion;return new LlmUsage("mapaf.llm.usage/v1",promptTokens,completionTokens,promptTokens+completionTokens,cost);}}
